/** Check-state glyph, 16 dp: shape and colour per state (01 §1.5); the word always stands next to it. */
@Composable
fun SbCheckStateGlyph(result: SbCheckResult, modifier: Modifier = Modifier) {
    val c = SebaroTheme.colors
    val (icon, tint) = when (result) {
        SbCheckResult.Passed -> SebaroIcons.Filled16.Success to c.success
        SbCheckResult.Open -> SebaroIcons.Outline16.Pending to c.warning
        SbCheckResult.Skipped -> SebaroIcons.Outline16.Skipped to c.info
        SbCheckResult.Failed -> SebaroIcons.Filled16.Error to c.danger
    }
    Icon(icon, contentDescription = null, tint = tint, modifier = modifier.size(SebaroTheme.tokens.size.iconSm))
}

/** „Beispieldaten“ in a 1 dp border-strong frame, radius 4, caption (FACTS-CONTRACT §8.5 f). */
@Composable
fun SbDemoMarker(text: String, modifier: Modifier = Modifier) {
    val t = SebaroTheme.tokens
    Text(
        text,
        style = SebaroTheme.typography.caption,
        color = SebaroTheme.colors.text,
        modifier = modifier
            .border(t.borderWidth.control, SebaroTheme.colors.borderStrong, t.shapes.small)
            .padding(horizontal = t.space.s2, vertical = 1.dp),   // the web's padding: 1px 8px, as SbTag
    )
}

/** The stale notice (FACTS-CONTRACT §8.3): warning glyph + the notice in text; replaces every claim. */
@Composable
fun SbStaleNotice(text: String, modifier: Modifier = Modifier) {
    val t = SebaroTheme.tokens
    Row(
        modifier.fillMaxWidth().padding(horizontal = t.spacing.gutter, vertical = t.space.s3),
        horizontalArrangement = Arrangement.spacedBy(t.space.s2),
        verticalAlignment = Alignment.Top,
    ) {
        Icon(
            SebaroIcons.Filled16.Warning,
            contentDescription = null,
            tint = SebaroTheme.colors.warning,
            modifier = Modifier.padding(top = t.space.s0_5).size(t.size.iconSm),
        )
        Text(text, style = SebaroTheme.typography.body, color = SebaroTheme.colors.text)
    }
}

/** Per-action hint (FACTS-CONTRACT §8.5 d) under an action that is not the primary action. */
@Composable
fun SbActionHint(text: String, modifier: Modifier = Modifier) {
    Text(text, style = SebaroTheme.typography.caption, color = SebaroTheme.colors.textMuted, modifier = modifier)
}

/** A row of the full form: the refs of its note, the claim (when shown) and the label (when not verified). */
@Immutable
data class SbFactRow(val refs: List<String>, val claim: String, val label: String)

/**
 * The full form (b) as claim rows (D40): one SbClaimRow per row whose note exists, hairlines between them; stale
 * shows the notice instead of every row. Ends with the check summary, one state per line, and „Wie geprüft?“.
 */
@Composable
fun SbClaimRows(
    notes: SbNotes,
    rows: List<SbFactRow>,
    todayIso: String,
    onHowChecked: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    Column(modifier.fillMaxWidth()) {
        if (notes.isStale(todayIso)) {
            SbStaleNotice(notes.staleNotice ?: "")
        } else {
            var first = true
            rows.forEach { row ->
                val note = notes.note(*row.refs.toTypedArray()) ?: return@forEach
                if (!first) {
                    Box(
                        Modifier
                            .padding(start = t.spacing.gutter)
                            .fillMaxWidth()
                            .height(t.borderWidth.hairline)
                            .background(c.border),
                    )
                }
                first = false
                SbClaimRow(text = if (note.showsClaim) row.claim else row.label, note = note, onHowChecked = onHowChecked)
            }
        }
        Column(
            Modifier.padding(horizontal = t.spacing.gutter, vertical = t.space.s3),
            verticalArrangement = Arrangement.spacedBy(t.space.s1),
        ) {
            SbCheckResult.entries.forEach { result ->
                val n = notes.count(result)
                if (n > 0) {
                    val word = notes.checks.first { it.result == result }.stateWord
                    Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
                        SbCheckStateGlyph(result)
                        Text("$n $word", style = ty.caption, color = c.text)
                    }
                }
            }
            // lines up with the counts above, as the web's plain link (no side padding); the target reaches 8 dp into
            // the gutter
            SbTextAction(sbMessages().howChecked, onHowChecked, Modifier.offset(x = -t.space.s2))
        }
    }
}

/** The check list „Wie geprüft?“ (c): every check in execution order, one below the other. */
@Composable
fun SbCheckList(notes: SbNotes, modifier: Modifier = Modifier) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    Column(modifier.fillMaxWidth()) {
        notes.checks.forEachIndexed { index, check ->
            if (index > 0) {
                Box(Modifier.fillMaxWidth().height(t.borderWidth.hairline).background(c.border))
            }
            Column(
                Modifier.fillMaxWidth().padding(horizontal = t.spacing.gutter, vertical = t.space.s3),
                verticalArrangement = Arrangement.spacedBy(t.space.s0_5),
            ) {
                Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(t.space.s1)) {
                    SbCheckStateGlyph(check.result)
                    Text(check.stateWord, style = ty.label, color = c.text)
                }
                Text(check.title, style = ty.body, color = c.text)
                val meta = listOfNotNull(check.date, check.by).joinToString(" · ")
                if (meta.isNotEmpty()) Text(meta, style = ty.caption, color = c.textMuted)
                check.reason?.let { Text(m.checkReason(it), style = ty.caption, color = c.text) }
                check.limit?.let { Text(it, style = ty.caption, color = c.text) }
                check.evidence.forEach { Text(it, style = ty.code, color = c.textMuted) }
            }
        }
    }
}
